/*
 * ISO-Zeitstempel für MariaDB DATETIME(3) formatieren.
 *
 * Beispiel:
 * 2026-07-23T21:53:18.000Z
 *
 * wird zu:
 * 2026-07-23 21:53:18.000
 *
 * Die Zeit bleibt UTC.
 */
function datumFuerMariaDb(value) {
    if (!value) {
        return null;
    }

    const text = String(value).trim();

    /*
     * Format 1:
     * DD.MM.YYYY HH:mm:ss
     */
    let match = text.match(
        /^(\d{2})\.(\d{2})\.(\d{4})\s+(\d{2}):(\d{2}):(\d{2})(?:\.(\d{1,3}))?$/
    );

    if (match) {
        const tag = Number(match[1]);
        const monat = Number(match[2]);
        const jahr = Number(match[3]);
        const stunde = Number(match[4]);
        const minute = Number(match[5]);
        const sekunde = Number(match[6]);
        const millisekunden = match[7]
            ? match[7].padEnd(3, "0")
            : "000";

        if (
            monat < 1 || monat > 12 ||
            tag < 1 || tag > 31 ||
            stunde > 23 ||
            minute > 59 ||
            sekunde > 59
        ) {
            return null;
        }

        return (
            String(jahr).padStart(4, "0") + "-" +
            String(monat).padStart(2, "0") + "-" +
            String(tag).padStart(2, "0") + " " +
            String(stunde).padStart(2, "0") + ":" +
            String(minute).padStart(2, "0") + ":" +
            String(sekunde).padStart(2, "0") + "." +
            millisekunden
        );
    }

    /*
     * Format 2:
     * ISO-Zeitstempel
     */
    const datum = new Date(text);

    if (!Number.isNaN(datum.getTime())) {
        return datum
            .toISOString()
            .replace("T", " ")
            .replace("Z", "");
    }

    return null;
}


