const werte = [];

for (const datensatz of msg.payload) {

    if (!datensatz || !datensatz.col1) {
        node.warn("Datensatz ohne col1 übersprungen");
        continue;
    }

    const beginn = datumFuerMariaDb(datensatz.col2);
    const ende = datumFuerMariaDb(datensatz.col3);

    if (!beginn) {
        node.warn(
            "Datensatz mit ungültigem Beginn übersprungen: " +
            JSON.stringify(datensatz)
        );
        continue;
    }

    platzhalter.push("(?, ?, ?, ?, ?)");

    werte.push(
        String(datensatz.col1),
        beginn,
        ende,
        datensatz.col5
            ? String(datensatz.col5)
            : null,
        msg.sourceFile
            ? String(msg.sourceFile)
            : null
    );
}


